// @FunctionalInterface permite composicion
@FunctionalInterface
interface Transformador<T, R> {
    R transformar(T entrada);

    default <V> Transformador<T, V> yLuego(Transformador<R, V> siguiente) {
        return entrada -> siguiente.transformar(this.transformar(entrada));
    }
}

