import java.util.stream.*;
import java.util.*;

record Producto(String nombre, double precio) {}

List<Producto> productos = List.of(
    new Producto("Laptop", 999.99),
    new Producto("Mouse", 29.99),
    new Producto("Teclado", 79.99)
);

// BIEN con stream: transformacion funcional clara
List<String> nombresCaros = productos.stream()
    .filter(p -> p.precio() > 50)
    .map(Producto::nombre)
    .toList();

// BIEN con for: efectos secundarios complejos o break/continue
StringBuilder reporte = new StringBuilder();
for (Producto p : productos) {
    if (p.precio() < 0) {
        continue;  // saltar invalidos
    }
    reporte.append(p.nombre())
           .append(": $")
           .append(p.precio())
           .append("\n");
    if (reporte.length() > 200) {
        break;  // cortar si muy largo
    }
}

// BIEN con stream: operaciones encadenadas y terminales
double sumaTotal = productos.stream()
    .mapToDouble(Producto::precio)
    .sum();

// BIEN con for: iterar con indice
for (int i = 0; i < productos.size(); i++) {
    Producto p = productos.get(i);
    System.out.println(i + ": " + p.nombre());
}
